const templateCategories=[["all", "All Templates"], ["barber", "Barber Shop"], ["hair", "Hair Studio"], ["beauty", "Beauty & Bridal"], ["nails", "Nails & Lashes"], ["spa", "Spa & Massage"], ["ayurvedic", "Ayurvedic Wellness"], ["skin", "Skin Clinic"], ["tattoo", "Tattoo Studio"]];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const templateCard=t=>`<article class="template live-template" data-template-id="${t.id}" data-category="${t.category}" data-name="${escapeHtml((t.name+' '+t.category+' '+t.tagline).toLowerCase())}"><button type="button" class="live-template-photo studioflow-cover" data-template-preview="${t.id}" aria-label="View ${escapeHtml(t.name)} template details"><img src="${t.image}" alt="${escapeHtml(t.businessName)} cover from Studioflow" width="700" height="600" loading="lazy" decoding="async"><span class="live-badge">STUDIOFLOW TEMPLATE</span><span class="preview-chip">View Template ↗</span></button><div class="live-template-content"><span class="tag">${escapeHtml(templateCategories.find(c=>c[0]===t.category)?.[1]||t.category)}</span><h3>${escapeHtml(t.name)}</h3><p>${escapeHtml(t.tagline)}</p><p class="note">${escapeHtml(t.palette)}</p><div class="template-actions"><button class="btn small outline" type="button" data-template-preview="${t.id}">View Template <span aria-hidden="true">↗</span></button>${btn('Use in Studioflow',t.customizeUrl,'small')}</div></div></article>`;
const templateCollection=()=>`<div class="search"><input id="template-search" aria-label="Search live templates" placeholder="Search barber, hair, nails, spa, tattoo…"></div><div class="filter" id="template-filter" aria-label="Template categories">${templateCategories.map((c,i)=>`<button data-template-category="${c[0]}" class="${i===0?'selected':''}" aria-pressed="${i===0}">${c[1]}</button>`).join('')}</div><p id="template-count" class="note" aria-live="polite">Showing all ${liveTemplates.length} Studioflow templates</p><div class="live-template-grid" id="template-grid">${liveTemplates.map(templateCard).join('')}</div><p id="template-empty" hidden>No matching templates. Try another search or category.</p>`;
const templatesSection=()=>`<section class="section soft"><div class="wrap"><div class="split"><div><div class="eyebrow">NEXORA SITES</div><h2>More Than a Website.<br>Your Digital Beauty Storefront.</h2><p>Launch your beauty business online with a free Nexora presence. Your services, your portfolio, your people—all under your own identity.</p>${checks(['Free website setup','Mobile-first design','Service menu and price catalogue','Portfolio, gallery, maps and WhatsApp contact','Enquiry and appointment-ready profile','Growth Partner onboarding support'])}<div class="actions">${btn('Explore All Templates','https://nexora-one-white-label.templateapp67.chatgpt.site/')}${btn('Create My Free Website','https://nexora-one-white-label.templateapp67.chatgpt.site/','light')}</div></div><div class="rewards-art"><div class="mock" style="height:330px;width:100%;transform:rotate(3deg);box-shadow:0 25px 55px #30204a38"><img src="/salon.webp" loading="lazy" alt="Salon hair stylist at work"><div class="mock-text"><small>THE ATELIER · HAIR & BEAUTY</small><strong style="font-size:42px;max-width:230px">A little change.<br>A whole new you.</strong><small>EXPLORE SERVICES &nbsp; →</small></div></div></div></div><div class="head" style="margin-top:65px"><div><h3>A design for every kind of beauty.</h3><p>All 14 beauty and wellness templates from Studioflow.</p></div><a class="link" href="${'https://nexora-one-white-label.templateapp67.chatgpt.site/'}">Open Studioflow Builder ↗</a></div>${templateCollection()}<p class="note">View each template’s design details and sample services here. Use in Studioflow opens the builder; sign in, then choose the matching template to customize. <a class="link" href="https://github.com/templateapp67-oss/studioflow">Studioflow source ↗</a></p></div></section>`;
const stepsSection=()=>`<section class="section dark"><div class="wrap"><div class="eyebrow">LOCAL PEOPLE. LASTING IMPACT.</div><h2>A Growth Partner Behind<br>Every Growth Story.</h2><p style="max-width:650px">Digital growth should never feel complicated. Local Growth Partners help beauty businesses get started, from profile setup to portfolio readiness and digital visibility.</p><div class="steps">${[['Connect','A local partner connects with a beauty business.'],['Launch','Choose the right template and build a free business presence.'],['Activate','Verify services, portfolio, location and business details.'],['Grow','Join discovery, customer engagement, jobs and marketplace opportunities.']].map((s,i)=>`<div class="step"><span class="num">0${i+1} /</span><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div><div class="actions">${btn('Learn About Growth Partners','/growth-partner/')}</div></div></section>`;
const activationCommission=()=>`<article class="activation-card" aria-labelledby="activation-title"><span class="mini-tag">FIRST 15 DAYS · ONE-TIME</span><h3 id="activation-title">One-Time Activation Commission</h3><p>First 15 days ke active Nexora platform revenue par <strong>10% one-time activation commission.</strong></p><div class="activation-example"><span>Illustrative example</span><p>₹100/day × 15 days = ₹1,500 <span aria-hidden="true">→</span> <strong>Partner gets ₹150</strong></p></div><p class="note">Commission applies to eligible, verified platform revenue and is subject to program terms. This example is not a guaranteed earning promise.</p></article>`;
const payouts=()=>`<h3>Earn Beyond Milestones.</h3><p>Performance-linked payouts may apply to eligible, successfully collected and verified paid onboarding or service collections associated with businesses you onboard.</p><div class="payouts">${[['First 6 months','10%'],['Months 6–12','5%'],['After 12 months','2%']].map(p=>`<div class="payout"><span>${p[0]}</span><strong>${p[1]}</strong><small>of Nexora’s eligible company share${p[1]==='2%'?' · loyalty payout':''}</small></div>`).join('')}</div><details><summary>How payouts work · see the calculation</summary><p>For an eligible ₹15,000 collection, if Nexora’s share is 10%, the eligible company share is ₹1,500. A 10% partner payout from that share is ₹150.</p><p>For an eligible ₹1,000 collection, Nexora’s 10% share is ₹100. The partner’s 10% payout from that company share is ₹10.</p><label class="field">Try an eligible collection amount (₹)<input id="collection" type="number" min="0" max="100000000" value="15000"></label><p id="calculation" aria-live="polite">Illustrative partner payout: ₹150</p><p class="note">This is an illustrative calculation, not a guaranteed earning promise. Payouts apply only after refunds, cancellations, chargebacks, taxes and applicable deductions. No payment is made merely for recruiting another Growth Partner. Continued eligibility and program terms apply.</p></details>`;
const rewardProducts=[['tshirt','A white T-shirt, sample photo; final Nexora branding may differ'],['tablet','Samsung Galaxy Tab S9 tablet product photo'],['laptop','HP laptop product photo'],['scooter','Ather Rizta electric scooter product photo'],['iphone','Apple iPhone product photo'],['motorcycle','Royal Enfield Classic 350 motorcycle product photo'],['suv','Mahindra Scorpio-N SUV product photo']];
const milestonesSection=()=>`<section class="section dark" style="background:#1b1527"><div class="wrap"><div class="head"><div><div class="eyebrow">REAL VALUE. MEANINGFUL MILESTONES.</div><h2>Create Real Business Value.<br>Unlock Real Milestones.</h2></div><p>Recognition for verified, active business onboarding and eligible performance.</p></div><div class="milestones">${[['♧','25','Official Nexora T-Shirt'],['▣','50','Samsung Tablet'],['▱','100','Branded HP Laptop'],['⚡','250','Electric Scooter'],['▯','500','Latest iPhone'],['◉','750','Royal Enfield 350 cc'],['◇','1000+','District Partner Eligibility + SUV Car Reward']].map((m,i)=>`<div class="milestone"><button class="reward-photo" data-reward="${i}" aria-label="View larger photo of ${m[2]}"><img src="/assets/rewards/${rewardProducts[i][0]}.webp" alt="${rewardProducts[i][1]}" width="800" height="700" loading="lazy" decoding="async"><span class="photo-zoom" aria-hidden="true">⤢</span></button><div class="milestone-info"><strong>${m[1]}</strong><small>VERIFIED ACTIVE SHOPS</small><h4>${m[2]}</h4></div></div>`).join('')}</div><p class="note">Photos show representative products; the T-shirt photo is a sample, not the final Nexora design. Exact models, colours and branding may vary. Rewards are subject to verified active business status, milestones, applicable program terms, availability, tax requirements and fulfilment conditions. An equivalent model, product or value may be provided. Rewards are not guaranteed.</p>${activationCommission()}${payouts()}<div class="actions">${btn('Become a Growth Partner',BASE+'/partner')}${btn('View Program Terms','/policies/?section=growth-partner-terms','outline')}</div></div></section>`;
const rewardsSection=()=>`<section class="section white"><div class="wrap split"><div class="rewards-art"><div class="reward-pass"><div class="logo" style="font-size:16px">NEXORA <span style="font-weight:400">/ REWARDS</span></div><h3>Great experiences.<br>More possibilities.</h3><div class="level">✧ &nbsp; YOUR BEAUTY JOURNEY, REWARDED</div><p style="font-size:10px;color:#c0b4d3;margin:20px 0 0">ILLUSTRATIVE MEMBER CARD</p></div></div><div><div class="eyebrow">NEXORA REWARDS</div><h2>Every Beauty Experience<br>Can Give Back.</h2><p>Eligible completed actions can unlock benefits across the Nexora network.</p>${checks(['Points on eligible completed bookings','Rewards for verified feedback','Referral benefits','Birthday and member offers','Eligible redemptions and reward tiers'])}<p class="note">Reviews are never rewarded based on whether they are positive or negative.</p>${btn('Explore Nexora Rewards','/rewards/')}</div></div></section>`;
const jobsSection=()=>`<section class="section"><div class="wrap split"><div><div class="eyebrow">NEXORA JOBS</div><h2>Good Talent.<br>Great Possibilities.</h2><p>The beauty industry’s opportunity network. Find meaningful work or connect with the people who can help your business grow.</p><div>${jobs.slice(0,8).map(j=>`<a class="pill" href="/jobs/?role=${encodeURIComponent(j)}">${j} ↗</a>`).join('')}</div><div class="actions">${btn('I’m Looking for Work','/jobs/')}${btn('Post a Job','/jobs/?action=post','light')}</div></div><img class="rounded" src="/assets/barber.webp" loading="lazy" alt="Professional barber cutting a client’s hair"></div></section>`;
const marketSection=()=>`<section class="section soft"><div class="wrap"><div class="head"><div><div class="eyebrow">NEXORA MARKET</div><h2>Everything Your Business<br>Needs to Keep Growing.</h2></div><p>Professional products, furniture, machines, consumables and training. A marketplace built around beauty businesses.</p></div><div class="grid">${markets.slice(0,6).map((m,i)=>`<a href="/marketplace/?category=${encodeURIComponent(m)}" class="card"><span class="icon">${['✦','◈','▥','≈','✎','✧'][i]}</span><h3>${m}</h3><span class="link">Explore category ↗</span></a>`).join('')}</div><div class="actions">${btn('Explore Nexora Market','/marketplace/')}${btn('Become a Seller','/marketplace/?action=sell','light')}</div></div></section>`;
const whySection=()=>`<section class="section white"><div class="wrap"><div class="eyebrow">WHY NEXORA?</div><h2>Less Fragmentation.<br>More Connection.</h2><div class="comparison"><div><span class="tag">THE FRAGMENTED EXPERIENCE</span><h3>More tools. More moving parts.</h3>${checks(['Separate booking tools and websites','Disconnected job portals and supplier contacts','Limited local onboarding support','Limited customer retention tools','High dependency on third-party platforms'])}</div><div class="connected"><span class="tag">THE NEXORA VISION</span><h3>One network. Your own brand.</h3>${checks(['Discover, book, build, hire, sell and grow','Free website presence and industry templates','Local Growth Partner onboarding support','Business, jobs, market and rewards together','Built to grow from local to global'])}<p class="note">Booking fees, services and commercial terms depend on the selected offering. Refer to the applicable plan.</p></div></div></div></section>`;
const home=()=>`<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">ONE ECOSYSTEM FOR THE BEAUTY INDUSTRY</div><h1>Beauty Meets Growth.<br><span>Everything<br>Connects.</span></h1><p class="lead">Nexora connects customers, beauty businesses, professionals, suppliers and Growth Partners in one powerful digital ecosystem.</p><div class="actions">${btn('Explore Nexora','#ecosystem')}${btn('Join Nexora Free',SIGNUP_URL,'outline')}</div><div class="micro"><a href="/business/">I’m a Business Owner ↗</a><a href="/jobs/">I’m Looking for Jobs ↗</a><a href="/marketplace/">I’m a Supplier ↗</a><a href="/growth-partner/">Become a Growth Partner ↗</a></div></div><div class="visual"><img class="hero-photo" src="/salon.webp" alt="Beauty professional styling a client’s hair" fetchpriority="high"><div class="hub"><strong>NEXORA</strong><small>EVERYTHING CONNECTS</small></div>${modules.map((m,i)=>`<a class="orbit o${i}" href="/${m[0]}/"><i aria-hidden="true">${m[1]}</i><span><b>${['Discover & Book','Nexora Business','Nexora Sites','Nexora Jobs','Nexora Market','Nexora Rewards','Growth Partners'][i]}</b><small>${['YOUR NEXT EXPERIENCE','YOUR BUSINESS, CONNECTED','BUILD YOUR OWN BRAND','SKILLS MEET OPPORTUNITY','EQUIP YOUR AMBITION','MORE FROM EVERY VISIT','LOCAL PEOPLE. REAL GROWTH.'][i]}</small></span></a>`).join('')}<span class="caption">DISCOVER. BOOK. BUILD. HIRE. SELL. GROW.</span></div></div></section><div class="strip"><div class="wrap"><strong>A PLACE FOR EVERY BEAUTY BUSINESS</strong>Salons · Barbers · Beauty Parlours · Spas · Tattoo Studios · Clinics · Artists · Academies · Brands · Suppliers</div></div>${ecosystem()}${audiences()}${templatesSection()}${stepsSection()}${milestonesSection()}${rewardsSection()}${jobsSection()}${marketSection()}${whySection()}<section class="section"><div class="wrap split"><div><div class="eyebrow">STARTING LOCAL. THINKING GLOBAL.</div><h2>The Future of Beauty<br>Is Connected.</h2><p>Every haircut, makeover, product order and career opportunity can be part of a stronger ecosystem. Nexora is building a connected future for the people who make beauty happen.</p><a class="link" href="/about/">Meet the Nexora vision ↗</a></div><div class="manifesto"><p>Local businesses.<br>Real professionals.<br>Better customer experiences.<br><strong style="color:var(--purple)">One connected network.</strong></p></div></div></section>`;
const subhero=(eyebrow,title,copy,img)=>`<section class="subhero"><div class="wrap split"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div><img src="/${img}" alt="${eyebrow} inspiration"></div></section>`;
const discover=()=>`${subhero('NEXORA DISCOVER','Your Next Beauty Experience Starts Here.','Explore the beauty and wellness world around you. Find the service, style and professional that feels right.','assets/spa.webp')}<section class="section"><div class="wrap"><div class="eyebrow">EXPLORE THE POSSIBILITIES</div><h2>What Are You Looking For?</h2><p>Illustrative service categories. Booking continues on the Nexora platform.</p><form class="search" id="discover-search"><input name="service" aria-label="Search service" placeholder="Hair, nails, spa, tattoo…"><input name="city" aria-label="Your city" placeholder="Your city"><button class="btn">Find services ↗</button></form><div class="filter" id="discover-filter"><button class="selected" data-filter="all">All experiences</button>${['Hair','Barber','Spa','Nails','Tattoo','Beauty'].map(x=>`<button data-filter="${x.toLowerCase()}">${x}</button>`).join('')}</div><div class="grid catalog" id="discover-grid">${[['Hair','Hair Studios','salon.webp'],['Barber','Barbers & Grooming','assets/barber.webp'],['Spa','Spa & Wellness','assets/spa.webp'],['Nails','Nail & Lash Studios','assets/nails.webp'],['Tattoo','Tattoo Artists','assets/tattoo.webp'],['Beauty','Beauty & Skin Care','assets/products.webp']].map(([cat,n,img])=>`<article class="card" data-category="${cat.toLowerCase()}"><img src="/${img}" alt="${n}" loading="lazy"><h3>${n}</h3><p>Explore services, portfolios and booking options.</p>${btn('Explore Services',BASE+'/?category='+encodeURIComponent(cat),'small')}</article>`).join('')}</div><p id="search-result" aria-live="polite"></p></div></section>`;
const business=()=>`${subhero('NEXORA BUSINESS','Your Business.<br>Your Brand.<br>Your Growth.','Bring your profile, services, appointments and customers together. A stronger digital presence starts with you.','salon.webp')}<section class="section"><div class="wrap split"><div><h2>Built Around Your Everyday.</h2>${checks(['Business profile, team and service catalogue','Appointment and customer management','Offers, gallery and portfolio','Location and contact details','Website template selection','Local onboarding support'])}${btn('Create My Business Profile',SIGNUP_URL)}</div><div class="card"><span class="tag">AN ILLUSTRATIVE WORKSPACE</span><h3>Your studio, at a glance.</h3><div class="check"><p>◉ &nbsp; Business profile <span class="mini-tag">Your brand</span></p><p>▧ &nbsp; Services & portfolio</p><p>▤ &nbsp; Appointments & customers</p><p>✧ &nbsp; Offers & engagement</p></div><a class="link" href="${LOGIN_URL}">Open your dashboard ↗</a></div></div></section>${templatesSection()}${stepsSection()}`;
