const marketPage=()=>`${subhero('NEXORA MARKET','Equip Your Ambition.','Products, tools, furniture, technology and training. Connect with what your beauty business needs next.','assets/products.webp')}<section class="section"><div class="wrap"><div class="head"><div><h2>A Marketplace Built for Beauty.</h2><p>Category showcase. Supplier listings and checkout are planned; no products are being sold on this landing site.</p></div><button class="btn" data-interest="Supplier">Become a Seller ↗</button></div><div class="search"><input id="market-search" aria-label="Search marketplace categories" placeholder="Find products, tools or equipment"></div><div class="grid" id="market-grid">${markets.map((m,i)=>`<article class="card" data-name="${m.toLowerCase()}"><span class="icon">${['✦','◈','▥','≈'][i%4]}</span><h3>${m}</h3><p>Connect with professional suppliers and explore business enquiries.</p><button class="btn small" data-interest="${m}">Get Updates ↗</button></article>`).join('')}</div><p id="market-empty" hidden>No matching categories.</p></div></section>`;
const partnerPage=()=>`${subhero('GROWTH PARTNER NETWORK','Build Beauty Businesses.<br>Build Your Future.','Help local salons, studios and wellness businesses go digital. Your local knowledge can open a new chapter for your community.','assets/team.webp')}<section class="section"><div class="wrap split"><div><div class="eyebrow">GROW TOGETHER</div><h2>Local Connections.<br>Real Business Value.</h2><p>Support onboarding, service catalogues, template selection and portfolio readiness. Performance is linked to eligible verified business activity.</p><div class="actions">${btn('Apply as a Growth Partner',BASE+'/partner')}${btn('Partner Dashboard',BASE+'/partner/dashboard','light')}</div><p class="note">This program is based on verified business value. Payouts and rewards are subject to eligibility and terms.</p></div><div class="card"><h3>Your Partner Journey</h3>${checks(['Create your partner profile','Connect with local beauty businesses','Help verified businesses launch','Track referrals in the partner dashboard','Unlock eligible performance milestones'])}</div></div></section>${stepsSection()}${milestonesSection()}`;
const rewardsPage=()=>`${subhero('NEXORA REWARDS','More From Every<br>Beauty Experience.','Eligible bookings, feedback and referrals can make your beauty journey more rewarding.','assets/nails.webp')}${rewardsSection()}<section class="section soft"><div class="wrap"><h2>Good Experiences. Fair Rewards.</h2>${checks(['Only eligible completed actions qualify','Feedback rewards never depend on a positive rating','Available benefits and tiers may vary','Refunded or cancelled transactions may not qualify'])}<details><summary>How do I start?</summary><p>Create your Nexora account and check the available rewards in your account. Specific benefits are subject to the live program terms.</p></details><details><summary>Are points shown here my real balance?</summary><p>No. The member card is a visual illustration. Your account is the source for any available balance.</p></details>${btn('Join Nexora Free',SIGNUP_URL)}</div></section>`;
const about=()=>`${subhero('ABOUT NEXORA','The Future of Beauty<br>Is Connected.','Nexora is building an operating system, marketplace and growth network for the complete beauty industry—starting local and designed to grow globally.','assets/team.webp')}<section class="section"><div class="wrap split"><div><h2>One Ecosystem.<br>Many Ways to Grow.</h2><p>Customers, salons, barbers, beauty parlours, spas, tattoo studios, clinics, independent professionals, academies, brands and suppliers all contribute to the beauty economy.</p><p>Our purpose is to bring those journeys together through discovery, digital presence, opportunities and local onboarding.</p><a class="link" href="/contact/">Connect with Nexora ↗</a></div><div class="manifesto"><p>Local businesses.<br>Real professionals.<br>Better customer experiences.<br><strong>One connected network.</strong></p></div></div></section>${ecosystem()}`;
const contactPage=()=>`${subhero('LET’S CONNECT','A Conversation Can<br>Start Something Great.','Tell us what you’re building, looking for or hoping to explore. Connect with the right Nexora pathway.','assets/team.webp')}<section class="section"><div class="wrap split"><div><h2>How Can We Help?</h2>${checks(['Business onboarding and website setup','Growth Partner opportunities','Supplier and brand enquiries','Enterprise and multi-location businesses'])}<p>कोई भी beauty business हो—digital growth की शुरुआत यहाँ से करें।</p><button class="btn" data-contact>Choose Your Pathway ↗</button></div><div class="card"><h3>Your Next Step</h3><p>Use the contact assistant to choose a topic and open the relevant Nexora account page. No personal details are submitted from this landing site.</p><a class="link" href="${SIGNUP_URL}">Create your Nexora account ↗</a></div></div></section>`;
const policies=()=>`<section class="section"><div class="wrap"><div class="eyebrow">POLICIES & TRUST</div><h1>Clear Terms.<br>Confident Decisions.</h1><p>Program information for this marketing website. Full binding policies must be provided by Nexora on the operating platform before transactions or program enrolment.</p>${legalNames.map(n=>`<details id="${slug(n)}"><summary>${n}</summary><p>${n==='Growth Partner Terms'||n==='Earnings Policy'?'Partner payouts are linked to eligible, successfully collected and verified business payments. Calculations exclude refunds, cancellations, chargebacks, taxes and applicable deductions. No payout is made merely for recruiting a partner. Rewards depend on verified active shops, milestone eligibility, availability, fulfilment and applicable program terms.':n==='Rewards Terms'?'Rewards apply only to eligible completed actions. Feedback rewards do not depend on whether a review is positive or negative. Availability, tiers, redemption rules and expiry depend on the live program.':n==='Privacy Policy'||n==='Cookie Policy'?'This landing website does not submit contact form details to a server. Interest reminders can be stored on this device only with your action and deleted below. External account links follow the operating platform’s privacy policy. Google Fonts loads typography; locally hosted illustrative photos are from Unsplash. No third-party analytics tracker is installed.':n==='Refund and Cancellation Policy'?'The applicable booking, seller and payment policies must be reviewed on the operating platform before payment. This landing website does not process bookings, payments, cancellations or refunds.':n==='Grievance Officer'?'An official grievance officer name and contact have not been supplied for this landing website. Use the operating platform’s official contact information; no contact identity is invented here.':'Access, listings, services and community participation are subject to eligibility and the full policy provided by Nexora on the operating platform. This page is informational and does not replace a final binding policy.'}</p></details>`).join('')}<button id="clear-interest" class="btn" style="margin-top:20px">Delete Device-Saved Interests</button></div></section>`;
const appPage=()=>`${subhero('NEXORA APP','Beauty, Growth and<br>Opportunity. On the Go.','A connected beauty experience in your pocket. Official download links will appear here when supplied.','assets/nails.webp')}<section class="section"><div class="wrap"><h2>Be Ready for What’s Next.</h2><p>App store links are not available on this site yet. Continue with Nexora on the web.</p>${btn('Open Nexora Web',BASE)}<button class="btn light" data-interest="Nexora App" style="margin-left:10px">Save App Interest ↗</button></div></section>`;
const route=location.pathname.split('/').filter(Boolean)[0]||'home';
const pages={home,discover,business,templates:templatesPage,jobs:jobsPage,marketplace:marketPage,'growth-partner':partnerPage,rewards:rewardsPage,about,contact:contactPage,policies,app:appPage};
